@page "/demo/tags"
@using Tempo.Blazor.Components.Tags
@using Tempo.Blazor.Interfaces

<TmTagPicker AllTags="@_allTags"
             SelectedTags="@_selectedTags"
             OnTagsChanged="@HandleTagsChanged"
             AllowCreate="true"
             OnCreateTag="@HandleCreateTag" />

@code {
    // --- ITag implementation ---
    private record AppTag(string Id, string Name, string Color) : ITag;

    // --- State ---
    private List<ITag> _allTags = new()
    {
        new AppTag("t1", "Bug",     "#ef4444"),
        new AppTag("t2", "Feature", "#3b82f6"),
        new AppTag("t3", "Docs",    "#10b981"),
    };

    private List<ITag> _selectedTags = new();

    // --- Handlers ---
    private void HandleTagsChanged(IEnumerable<ITag> updated)
        => _selectedTags = updated.ToList();

    private void HandleCreateTag(string name)
    {
        // Generate a new unique tag (in a real app persist to the server first)
        var newTag = new AppTag(
            Id:    Guid.NewGuid().ToString(),
            Name:  name,
            Color: "#8b5cf6");

        // Make it available in the dropdown for future use
        _allTags.Add(newTag);

        // Immediately select the newly created tag
        _selectedTags.Add(newTag);
    }
}
